// Auto-generated Nordic provider icon assets for Cloudflare Worker & Apple WeatherKit
const ICONS = {
    "METNorway_DMI.png": "",
    "METNorway.png": "",
    "DMI.png": "",
};

function base64ToUint8Array(base64) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

export function getNordicIcon(filename) {
    const b64 = ICONS[filename];
    if (!b64) return null;
    return base64ToUint8Array(b64);
}
